// ConnectErrorCode Why the server refused a connection, in `err.data.code` on `connect_error`. More
// codes can be added.
//
// Not retryable (reconnecting with the same key cannot succeed until something
// changes on your account): `MISSING_API_KEY`, `INVALID_API_KEY`,
// `API_KEY_DEACTIVATED`, `TIER_NO_WS`, `SUBSCRIPTION_INACTIVE`, `PAYMENT_OVERDUE`,
// `TRIAL_EXPIRED`, `TRIAL_UNVERIFIABLE`.
//
// Retryable: `SUBSCRIPTION_CHECK_FAILED`, `INTERNAL`, `IP_BLOCKED`,
// `CONNECTION_LIMIT` (every connection your plan allows is in use), `CLIENT_CLOSED`.
type ConnectErrorCode = string

// ConnectErrorData `err.data` on a `connect_error` the server refused. Absent from API versions that predate it.
type ConnectErrorData struct {
	// Code Why the server refused a connection, in `err.data.code` on `connect_error`. More
	// codes can be added.
	//
	// Not retryable (reconnecting with the same key cannot succeed until something
	// changes on your account): `MISSING_API_KEY`, `INVALID_API_KEY`,
	// `API_KEY_DEACTIVATED`, `TIER_NO_WS`, `SUBSCRIPTION_INACTIVE`, `PAYMENT_OVERDUE`,
	// `TRIAL_EXPIRED`, `TRIAL_UNVERIFIABLE`.
	//
	// Retryable: `SUBSCRIPTION_CHECK_FAILED`, `INTERNAL`, `IP_BLOCKED`,
	// `CONNECTION_LIMIT` (every connection your plan allows is in use), `CLIENT_CLOSED`.
	Code *ConnectErrorCode `json:"code,omitempty"`

	// MaxConnections On `CONNECTION_LIMIT`: how many connections your plan allows.
	MaxConnections *float64 `json:"maxConnections,omitempty"`

	// RetryAfterMs Wait at least this long before trying again.
	RetryAfterMs *float64 `json:"retryAfterMs,omitempty"`

	// Retryable True when reconnecting later with the same key can succeed.
	Retryable *bool `json:"retryable,omitempty"`
}

