// InjuryAgreement Whether the sources corroborate one another for this player.
type InjuryAgreement = string

// InjuryConsensus Derived agreement between sources. Present ONLY when the player's identity is
// certain; absent players are listed in `meta.unresolvedIdentity`.
type InjuryConsensus struct {
	// Agreement Whether the sources corroborate one another for this player.
	Agreement *InjuryAgreement `json:"agreement,omitempty"`

	// IDVerified True only when a shared player id corroborates the name-and-team join.
	IDVerified *bool `json:"idVerified,omitempty"`

	// InjuryStatus Null on a conflict: an indeterminate answer is its own verdict, never a pick.
	InjuryStatus *InjuryStatus `json:"injuryStatus,omitempty"`

	// ListDaysConflict True when both sources agree a player is on an injured list but disagree
	// about its length, for example 10 days against 60. `agreement` still reads
	// "agrees", so check this when the length matters.
	ListDaysConflict *bool               `json:"listDaysConflict,omitempty"`
	Sources          []InjurySourceLabel `json:"sources,omitempty"`

	// Stale Whether the designation is still current, judged against `staleAfterSeconds`.
	//
	// True when every dated record behind it is older than the window, false when
	// at least one is inside it, and null when no verdict is possible. Null is
	// never a substitute for false.
	Stale *bool `json:"stale,omitempty"`

	// StaleAfterSeconds The window the designation was judged against, in seconds, chosen by what the
	// designation IS rather than by sport alone: a weekly football designation
	// lapses far sooner than a baseball injured-list stint, which is given its own
	// length plus grace.
	//
	// Read it together with `stale` to tell the two nulls apart. A number beside a
	// null `stale` means the rule exists but nothing carried a timestamp. A null
	// here means no rule applies at all.
	StaleAfterSeconds *float64 `json:"staleAfterSeconds,omitempty"`

	// SuffixJoin True when the join bridged a name suffix. Disclosed rather than hidden.
	SuffixJoin *bool `json:"suffixJoin,omitempty"`
}

