// PropResultsResponse defines model for PropResultsResponse.
type PropResultsResponse struct {
	Data []PropResultEntry `json:"data,omitempty"`
	Meta *struct {
		// AbsentCategoryGroups Line groups for a player who IS in the box score but has no row for that
		// category. Expected for football - a quoted receiver with zero catches is in no
		// receiving group, so nothing is graded (never a 0, never a void). Kept apart from
		// `unmatchedLineGroups` so a real join failure is not buried in this benign count.
		AbsentCategoryGroups *float64 `json:"absentCategoryGroups,omitempty"`
		ActualsTruncated     *bool    `json:"actualsTruncated,omitempty"`

		// AmbiguousPlayers Players refused as `ambiguous_player`, with every spelling seen and which side
		// of the join proved it. `from: "lines"` with spellings differing only by a suffix
		// is the disclosed trade-off: from names alone that could be two people.
		AmbiguousPlayers []struct {
			From      *string  `json:"from,omitempty"`
			Key       *string  `json:"key,omitempty"`
			Spellings []string `json:"spellings,omitempty"`
		} `json:"ambiguousPlayers,omitempty"`
		CapturePhases []string `json:"capturePhases,omitempty"`

		// Checks What was actually evaluated to produce this response.
		Checks          []string `json:"checks,omitempty"`
		ConfirmedOnly   *bool    `json:"confirmedOnly,omitempty"`
		EntriesReturned *float64 `json:"entriesReturned,omitempty"`

		// EntryStatuses Status counts, ONE PER PLAYER-CATEGORY ENTRY - including entries no book quoted,
		// which contribute nothing to `lineOutcomes`. Use these for "how many players did
		// not play", never the line counts.
		EntryStatuses map[string]float64 `json:"entryStatuses,omitempty"`
		GameID        *string            `json:"gameId,omitempty"`

		// LineOutcomes Verdict counts, ONE PER BOOK LINE. `over + under + push` is a LINE count, so a
		// rate built from it is weighted by how many books quoted each player.
		LineOutcomes    map[string]float64 `json:"lineOutcomes,omitempty"`
		LinesGraded     *float64           `json:"linesGraded,omitempty"`
		LinesTruncated  *bool              `json:"linesTruncated,omitempty"`
		Message         *string            `json:"message,omitempty"`
		Mode            *string            `json:"mode,omitempty"`
		PlayersReturned *float64           `json:"playersReturned,omitempty"`

		// Provisional Entries returned that are still provisional. OVERLAPS `entryStatuses`.
		Provisional *float64 `json:"provisional,omitempty"`
		Sport       *string  `json:"sport,omitempty"`

		// SuffixGaps Joins that bridged a suffix - box score says "X Jr.", books say "X". Joined as
		// one player, usually rightly; disclosed because it is also the shape of the one
		// collision no name rule can see.
		SuffixGaps []struct {
			Actual *string  `json:"actual,omitempty"`
			Key    *string  `json:"key,omitempty"`
			Lines  []string `json:"lines,omitempty"`
		} `json:"suffixGaps,omitempty"`
		Timestamp *string `json:"timestamp,omitempty"`

		// UnmatchedLineExamples A few of those, named, so the mismatch can be chased.
		UnmatchedLineExamples []string `json:"unmatchedLineExamples,omitempty"`

		// UnmatchedLineGroups Closing-line groups no actual matched - a book quoted a player the box score did
		// not resolve under that spelling. Non-zero means the name join is losing data,
		// which otherwise looks exactly like "no book quoted this player".
		UnmatchedLineGroups *float64 `json:"unmatchedLineGroups,omitempty"`
	} `json:"meta,omitempty"`
	Success *bool `json:"success,omitempty"`
}

// PropTrendGame defines model for PropTrendGame.
