// ProphetXDeltaPayload Payload for the WebSocket `prophetx-update` event.
//
// Each delta contains ONLY the events (and within them, only the markets)
// that changed since the previous publish. Clients should accumulate deltas
// into their own state to maintain a full snapshot - or re-fetch the REST
// endpoint for the current full state.
type ProphetXDeltaPayload struct {
	Events []struct {
		Competitors []ProphetXCompetitor `json:"competitors,omitempty"`
		EventID     *float64             `json:"eventId,omitempty"`

		// Markets Changed markets only, keyed by `"{market_id}:{line}"`. See ProphetXMarket.
		Markets   map[string]ProphetXMarket `json:"markets,omitempty"`
		Name      *string                   `json:"name,omitempty"`
		Scheduled *string                   `json:"scheduled,omitempty"`
		Sport     *string                   `json:"sport,omitempty"`
		SportID   *float64                  `json:"sportId,omitempty"`

		// Status ProphetX status string (e.g. `not_started`, `live`, `ended`, `closed`).
		Status     *string `json:"status,omitempty"`
		Tournament *string `json:"tournament,omitempty"`
	} `json:"events,omitempty"`

	// Kind `game` = main game lines (moneyline/spread/total). `prop` = player/team props.
	Kind *ProphetXKind `json:"kind,omitempty"`

	// Sport Raw ProphetX sport name - e.g. `Basketball`, `Ice Hockey`, `Golf`.
	Sport *string `json:"sport,omitempty"`

	// SportSlug Valid ProphetX sport slugs accepted by REST filter and WS subscription.
	SportSlug *ProphetXSportSlug `json:"sportSlug,omitempty"`
	Timestamp *string            `json:"timestamp,omitempty"`
	Type      *string            `json:"type,omitempty"`
}

// ProphetXEventData One event inside a ProphetX REST response.
