// RealtimeFeedState Why this response is empty, when it is.
//
// `live`    - events were served.
// `unknown` - we cannot tell whether the feed is idle or broken.
//
// Deliberately only two states. Earlier drafts also had `idle` and `down`; both were
// removed after measurement. `down` was unreachable. `idle` keyed on the upstream
// reporting "connected, zero matchups", which it also reports when a live feed has
// frozen - so it could have claimed "nothing on" during an outage. Judge with
// `lastDataAgeSeconds`: a value in the hundreds of thousands means the feed has
// produced nothing for days.
type RealtimeFeedState struct {
	// LastDataAgeSeconds Seconds since this sport last produced ANY data, or `null` if it has not been
	// observed producing data. `null` does NOT mean healthy, and does not mean zero.
	LastDataAgeSeconds *float64 `json:"lastDataAgeSeconds,omitempty"`

	// Resubscribing True while the feed is subscribing again after a reconnect, when some leagues
	// can be silent. `null` means unknown, by the same rules as `upstreamAgeSeconds`.
	// Absent from API versions that predate it.
	Resubscribing *bool   `json:"resubscribing,omitempty"`
	State         *string `json:"state,omitempty"`

	// UpstreamAgeSeconds Seconds since Pinnacle last sent anything for this sport, as of this response.
	// `lastDataAgeSeconds` stays low while Pinnacle is quiet, because the board is
	// rewritten on a schedule either way; this keeps growing, so it is the field that
	// shows a feed that is running but hearing nothing.
	//
	// `null` means unknown: always when `meta.source` is not `"pinnacle"`, and before
	// the feed has received anything since it started. Absent from API versions that
	// predate it.
	UpstreamAgeSeconds *float64 `json:"upstreamAgeSeconds,omitempty"`
}

// RealtimeFreshness Freshness for the realtime endpoints, where `ageSeconds` can legitimately be
// unknown.
//
// Deliberately NOT a widening of OddsFreshness: `/odds` and `/events` share
// that type and customers do arithmetic directly on their `ageSeconds`, so loosening
// it there would force null-checks on consumers who do not need them today.
//
// `ageSeconds: null` means the age is genuinely unmeasurable - no source produced
// data and we have never observed this sport produce any. It replaced a reported
// `0`, which claimed the freshest possible data on a feed that had served nothing
// for four days. When null, `stale` is always `true`.
type RealtimeFreshness struct {
	// AgeSeconds Seconds since this data was produced, or `null` when that is unknowable.
	AgeSeconds *float64 `json:"ageSeconds,omitempty"`

	// DroppedAsFinished Events dropped because the match was confirmed finished (realtime only).
	DroppedAsFinished *float64 `json:"droppedAsFinished,omitempty"`

	// DroppedAsStale Events dropped because their scheduled start is older than the sport's
	// max plausible live duration - a source-independent staleness guard
	// (realtime only).
	DroppedAsStale *float64 `json:"droppedAsStale,omitempty"`
	Stale          *bool    `json:"stale,omitempty"`
}

