// SgpBuildResponse Response from `POST /api/v1/{sport}/sgp/build`.
//
// Also what a 422 returns. A 422 is NOT thrown, so check `success` before
// reading `sgp`, then branch on `reasonCode` (the API sends it on every 422 since
// the refusal-status change; older API versions sent none on a leg-resolution 422
// and threw the refusal as a 502):
//   - `"unresolved"`: a leg could not be resolved. No `sgp`, and a `reason` on each
//     unresolved leg naming which lines FanDuel does offer or why the category,
//     side or leg type cannot work. Fix the legs.
//   - any other SgpReasonCode (`line-mismatch`, `bet-failure`,
//     `not-placeable`, ...): FanDuel judged the slip and refused it, or its answer
//     did not confirm the legs as sent. The request was valid but cannot be priced
//     as specified, so do not resend the same body unchanged. `legIndex`,
//     `lineEchoed` and `failureCodes` are set where they apply; `message` is prose.
//
// Every other failure throws: a `ServiceBusyError` with `code` `no-price` when no
// usable answer came back (503, retry after `retryAfterMs`), one with an `SGP_*`
// code (SgpErrorBody in `details`), or, from older API versions, an
// `OwlsInsightError` with status 502 whose `details` is the
// SgpBuildErrorBody.
type SgpBuildResponse struct {
	// Code Repeats `reasonCode`.
	Code *string `json:"code,omitempty"`

	// Error Present when `success: false`.
	Error *string `json:"error,omitempty"`

	// FailureCodes Refused parlay only, when FanDuel rejected it with its own failure codes
	// (e.g. `SELECTION_NOT_FOUND`).
	FailureCodes []string `json:"failureCodes,omitempty"`

	// LegIndex Refused parlay, `line-*` codes only: the leg's index in your `legs` array.
	LegIndex *float64         `json:"legIndex,omitempty"`
	Legs     []SgpResolvedLeg `json:"legs,omitempty"`

	// LineEchoed Refused parlay, `line-*` codes only: the line FanDuel priced, exactly as it
	// sent it, or `null` when it sent none.
	LineEchoed *float64 `json:"lineEchoed,omitempty"`

	// Message Refused parlay (422) only: human-readable prose. Match on `reasonCode`,
	// `legIndex`, `lineEchoed` and `failureCodes`, never on this.
	Message *string `json:"message,omitempty"`

	// Meta `meta` of a `buildSgp` response (200, the leg-resolution 422 and the refused
	// 422), and of the no-price 503, `SGP_BUSY` 503 and legacy 502 error bodies.
	//
	// The fields marked "API v2.348.0" are absent from older API versions.
	Meta *SgpBuildMeta `json:"meta,omitempty"`

	// Pricing `"fanduel-slip"` on a 200: the price is FanDuel's own bet-slip answer.
	Pricing *string `json:"pricing,omitempty"`

	// ReasonCode Present when `success: false`: `"unresolved"` on a leg-resolution 422,
	// otherwise the SgpReasonCode of a refused parlay (never `no-price`,
	// which is thrown as a 503). Absent from older API versions' leg-resolution
	// 422.
	ReasonCode *string `json:"reasonCode,omitempty"`

	// Sgp The computed parlay price from a successful `buildSgp` call.
	Sgp     *SgpPrice `json:"sgp,omitempty"`
	Success *bool     `json:"success,omitempty"`
}

